import assert from 'node:assert/strict';
import test from 'node:test';
import fixture from './get_conversation_unread_summary-400.json' with { type: 'json' };
import { ClubhouseApiClient } from '../../src/api/client.ts';
import { FakeTransport } from '../../features/support/fakeTransport.ts';
import { documentedBodyKeys } from '../../src/api/documentedBodies.ts';

/** Generated by api:triage from a live failure. Empty {} caused 400; body is now {conversation_id}. */
test('live failure get_conversation_unread_summary 400 with empty body', async () => {
  const transport = new FakeTransport();
  transport.willAnswer(fixture.endpoint, fixture.status, 1);
  const client = new ClubhouseApiClient({
    useSandbox: false,
    webSession: true,
    experimentalActions: true,
    transport,
  });
  try {
    await client.callEndpoint(fixture.endpoint, {});
    assert.fail('expected the live failure status');
  } catch (err) {
    assert.ok(err);
  }
  assert.ok(client.getApiHealth().some((entry) => entry.endpoint === fixture.endpoint && entry.status === fixture.status));
});

test('get_conversation_unread_summary documents conversation_id', () => {
  assert.deepEqual(documentedBodyKeys('get_conversation_unread_summary'), ['conversation_id']);
  assert.equal(fixture.error, 'Conversation id is required.');
});
